command:
// Foundry VTT Macro: Редактор черт плоти (адаптации, увечья, врождённые недостатки)
// Создаёт, правит и удаляет предметы паков `biomancy_adaptations` и `mutilations`
// без консоли. Нужен потому, что три поля черты живут во ФЛАГАХ и в лист предмета
// не выведены: `flags.dedrel.rank` (ранг Модификатора «Адаптация», по нему селект
// Конструктора фильтрует опции), `flags.dedrel.divergence` (ступень расхождения,
// правила `_rules/16. Magic.md` §7.1) и `flags.dedrel.origin` (донор).
// Черта, заведённая руками через интерфейс, останется без этих флагов и в селекте
// Конструктора не появится вообще — молча, без ошибки.
//
// Что макрос НЕ трогает: Active Effects и длительность существующей черты.
// Механику правь в листе предмета — там она редактируется нормально. Новая черта
// создаётся без эффектов: заведи их в листе после создания.
//
// После любой правки — F5: реестр статусов пересобирается из компендиумов.
//
// V14: DialogV2 (Dialog deprecated), чтение формы через button.form.elements
// (FOUNDRY V14 QUIRKS §7, §9).
(async () => {
  if (!game.user.isGM) return ui.notifications.error("Макрос доступен только ГМу.");

  const PACKS = {
    "dedrel.biomancy_adaptations": "Адаптации (польза, согласной цели)",
    "dedrel.mutilations": "Увечья и врождённые недостатки"
  };
  const KEY_RE = /^[a-z0-9_]+$/;
  const esc = (v) => foundry.utils.escapeHTML(String(v ?? ""));

  // --- Сбор каталога ---
  const catalog = [];
  for (const packId of Object.keys(PACKS)) {
    const pack = game.packs.get(packId);
    if (!pack) return ui.notifications.error(`Компендиум ${packId} не найден.`);
    for (const doc of await pack.getDocuments()) {
      const f = doc.flags?.dedrel || {};
      catalog.push({
        doc, packId,
        key: doc.system?.key || "",
        name: doc.name,
        rank: f.rank ?? 0,
        divergence: f.divergence ?? 0,
        origin: Array.isArray(f.origin) ? f.origin.join(", ") : ""
      });
    }
  }
  catalog.sort((a, b) => a.packId.localeCompare(b.packId) || (a.rank - b.rank) || a.name.localeCompare(b.name));

  // --- Шаг 1: что делаем ---
  const options = [`<option value="">— создать новую черту —</option>`];
  let lastPack = null;
  for (const t of catalog) {
    if (t.packId !== lastPack) {
      if (lastPack !== null) options.push("</optgroup>");
      options.push(`<optgroup label="${esc(PACKS[t.packId])}">`);
      lastPack = t.packId;
    }
    const rank = t.rank ? `ранг ${t.rank}` : "без ранга";
    options.push(`<option value="${esc(t.key)}">${esc(t.name)} — ${rank}, ступень ${t.divergence || "—"}</option>`);
  }
  if (lastPack !== null) options.push("</optgroup>");

  const step1 = await foundry.applications.api.DialogV2.wait({
    window: { title: "Черты плоти" },
    position: { width: 560 },
    content: `
      <p class="hint" style="font-size:12px;">Ранг, ступень расхождения и донор в лист предмета не выведены — правятся только здесь. Механика (Active Effects) правится в листе.</p>
      <div class="form-group" style="display:flex; align-items:center; gap:10px;">
        <label style="flex:0 0 90px;">Черта</label>
        <select name="target" style="flex:1;">${options.join("")}</select>
      </div>`,
    buttons: [
      { action: "edit", label: "Править / создать", icon: "fa-solid fa-pen", default: true,
        callback: (e, b) => ({ action: "edit", key: b.form.elements.target.value }) },
      { action: "remove", label: "Удалить", icon: "fa-solid fa-trash",
        callback: (e, b) => ({ action: "remove", key: b.form.elements.target.value }) },
      { action: "cancel", label: "Отмена", callback: () => null }
    ],
    rejectClose: false
  });
  if (!step1) return;

  const existing = step1.key ? catalog.find(t => t.key === step1.key) : null;

  // --- Ветка удаления ---
  if (step1.action === "remove") {
    if (!existing) return ui.notifications.warn("Для удаления выберите существующую черту.");
    const sure = await foundry.applications.api.DialogV2.confirm({
      window: { title: "Удаление черты" },
      content: `<p>Удалить <b>${esc(existing.name)}</b> (<code>${esc(existing.key)}</code>) из <b>${esc(PACKS[existing.packId])}</b>?</p>
                <p style="color:#a33;">Предмет удаляется навсегда. Заклинания, уже ссылающиеся на этот ключ, перестанут накладывать черту.</p>`,
      rejectClose: false, modal: true
    });
    if (!sure) return;

    const pack = game.packs.get(existing.packId);
    const wasLocked = pack.locked;
    if (wasLocked) await pack.configure({ locked: false });
    try {
      await existing.doc.delete();
      ui.notifications.info(`Черта «${existing.name}» удалена. Нажмите F5.`);
      console.log("Dedrel | Черта плоти удалена:", existing.key);
    } catch (err) {
      console.error("Dedrel | Удаление черты провалилось", err);
      ui.notifications.error(`Не удалось удалить: ${err.message}`);
    } finally {
      if (wasLocked) await pack.configure({ locked: true });
    }
    return;
  }

  // --- Ветка создания/правки ---
  const cur = existing || { packId: "dedrel.biomancy_adaptations", key: "", name: "", rank: 1, divergence: 1, origin: "" };
  const curDesc = existing ? (existing.doc.system?.description || "") : "";
  const curImg = existing ? existing.doc.img : "systems/dedrel/assets/icons/conditions/body-balance.svg";

  const packOpts = Object.entries(PACKS)
    .map(([id, label]) => `<option value="${id}" ${cur.packId === id ? "selected" : ""}>${esc(label)}</option>`).join("");
  const rankOpts = [0, 1, 2, 3, 4, 5]
    .map(r => `<option value="${r}" ${cur.rank === r ? "selected" : ""}>${r === 0 ? "без ранга (врождённый недостаток)" : r}</option>`).join("");
  const divOpts = [
    [1, "1 — тело и так умеет (обычная сборка)"],
    [2, "2 — чужая струна (длинный каст + донор)"],
    [3, "3 — против вида (ритуал, вне обычной игры)"],
    [0, "— не применимо (врождённое)"]
  ].map(([v, l]) => `<option value="${v}" ${cur.divergence === v ? "selected" : ""}>${esc(l)}</option>`).join("");

  const row = (label, field) => `
    <div class="form-group" style="display:flex; align-items:center; gap:10px; margin-bottom:6px;">
      <label style="flex:0 0 150px; font-size:12px;">${label}</label>${field}
    </div>`;

  const form = await foundry.applications.api.DialogV2.prompt({
    window: { title: existing ? `Правка: ${existing.name}` : "Новая черта плоти" },
    position: { width: 620 },
    content: `
      ${row("Компендиум", existing
        ? `<span style="flex:1; font-size:12px; opacity:.8;">${esc(PACKS[cur.packId])} <em>(перенос между паками не поддержан)</em></span>`
        : `<select name="packId" style="flex:1;">${packOpts}</select>`)}
      ${row("Ключ (латиница)", existing
        ? `<code style="flex:1;">${esc(cur.key)}</code>`
        : `<input type="text" name="key" value="" placeholder="adapt_hollow_bones" style="flex:1;"/>`)}
      ${row("Название", `<input type="text" name="name" value="${esc(cur.name)}" style="flex:1;"/>`)}
      ${row("Ранг Адаптации", `<select name="rank" style="flex:1;">${rankOpts}</select>`)}
      ${row("Ступень расхождения", `<select name="divergence" style="flex:1;">${divOpts}</select>`)}
      ${row("Донор", `<input type="text" name="origin" value="${esc(cur.origin)}" placeholder="demon 3, dragon 5 либо beast" style="flex:1;"/>`)}
      ${row("Иконка", `<input type="text" name="img" value="${esc(curImg)}" style="flex:1;"/>`)}
      <div class="form-group" style="margin-bottom:6px;">
        <label style="font-size:12px;">Описание (HTML)</label>
        <textarea name="description" rows="7" style="width:100%;">${esc(curDesc)}</textarea>
      </div>
      <p class="hint" style="font-size:11px;">Ранг обязателен, чтобы черта попала в селект Модификатора «Адаптация»: селект показывает только черты, чей ранг равен рангу Модификатора. «Без ранга» — для врождённых недостатков, которые Биомантия не лепит.</p>
      ${existing ? `<p class="hint" style="font-size:11px;">Active Effects и длительность этой черты макрос не трогает.</p>` : ""}`,
    ok: { label: existing ? "Сохранить" : "Создать", icon: "fa-solid fa-floppy-disk",
      callback: (e, b) => ({
        packId: b.form.elements.packId?.value || cur.packId,
        key: b.form.elements.key?.value?.trim() || cur.key,
        name: b.form.elements.name.value.trim(),
        rank: Number(b.form.elements.rank.value) || 0,
        divergence: Number(b.form.elements.divergence.value) || 0,
        origin: b.form.elements.origin.value.split(",").map(x => x.trim()).filter(Boolean),
        img: b.form.elements.img.value.trim(),
        description: b.form.elements.description.value
      }) },
    rejectClose: false
  });
  if (!form) return;

  // --- Проверки ---
  if (!form.name) return ui.notifications.error("Название не может быть пустым.");
  if (!KEY_RE.test(form.key)) {
    return ui.notifications.error(`Ключ «${form.key}» должен быть в snake_case (строчная латиница, цифры, подчёркивание) — иначе «Валидация данных» пометит его ошибкой.`);
  }
  if (!existing && catalog.some(t => t.key === form.key)) {
    return ui.notifications.error(`Ключ «${form.key}» уже занят чертой «${catalog.find(t => t.key === form.key).name}».`);
  }
  if (form.divergence === 2 && form.origin.length === 0) {
    return ui.notifications.error("Ступень 2 требует донора: укажите Линию крови с рангом (например «demon 3») либо «beast».");
  }

  const pack = game.packs.get(form.packId);
  const wasLocked = pack.locked;
  if (wasLocked) await pack.configure({ locked: false });

  try {
    if (existing) {
      await existing.doc.update({
        name: form.name,
        img: form.img,
        "system.description": form.description,
        "flags.dedrel.rank": form.rank,
        "flags.dedrel.divergence": form.divergence,
        "flags.dedrel.origin": form.origin
      });
      ui.notifications.info(`Черта «${form.name}» обновлена. Нажмите F5.`);
      console.log("Dedrel | Черта плоти обновлена:", form);
    } else {
      // Новая черта: без эффектов (механику заводит автор в листе предмета).
      // Длительность — как у остальных адаптаций (Ранг Доктрины раундов, по
      // умолчанию 3); черта без ранга считается врождённой и не истекает.
      const created = await Item.createDocuments([{
        name: form.name,
        type: "condition",
        img: form.img,
        flags: { dedrel: { rank: form.rank, divergence: form.divergence, origin: form.origin } },
        system: {
          key: form.key,
          description: form.description,
          category: "negative",
          is_technical: false,
          stackable: false,
          max_stacks: 1,
          refresh_on_stack: false,
          duration: form.rank ? { units: "rounds", value: 3 } : { units: "permanent", value: 0 },
          expiry_events: form.rank ? ["turnEnd"] : [],
          application_text: "",
          removal_text: "",
          system_flags: {},
          tick: { formula: "", is_heal: false, damage_type: "", trigger: "turnStart" }
        }
      }], { pack: form.packId });
      ui.notifications.info(`Черта «${form.name}» создана. Откройте её и заведите Active Effects, затем F5.`);
      console.log("Dedrel | Черта плоти создана:", form);
      created[0]?.sheet?.render(true);
    }
  } catch (err) {
    console.error("Dedrel | Правка черты плоти провалилась", err);
    ui.notifications.error(`Не удалось записать: ${err.message}`);
  } finally {
    if (wasLocked) await pack.configure({ locked: true });
  }
})();
